style.css:
/* Roblox Animated Background */

body {
    background: linear-gradient(-45deg, #ff0000, #1a1a1a, #2b2b2b, #ff3c3c);
    background-size: 400% 400%;
    animation: robloxGradient 12s ease infinite;
    color: white !important;
}

/* Smooth animated gradient */
@keyframes robloxGradient {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

/* Optional: Add Roblox logo watermark */
body::before {
    content: "";
    position: fixed;
    top: 50%;
    left: 50%;
    width: 400px;
    height: 400px;
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/7/7e/Roblox_Logo_2022.svg");
    background-repeat: no-repeat;
    background-size: contain;
    opacity: 0.05;
    transform: translate(-50%, -50%);
    pointer-events: none;
    z-index: 0;
}

/* Make content appear above background */
* {
    position: relative;
    z-index: 1;
}
